\begin{definition}
\label{def:5.1}
Let $L>0$ be a real number. A function $f:\mathbb{R}\to\mathbb{C}$ is called \emph{periodic with period $L$} (or \emph{$L$-periodic}) if, for every $x\in\mathbb{R}$, one has
\[
\label{eq:5.u1}
f(x+L)=f(x).
\]
\end{definition}

\begin{example}
The functions $\sin x$, $\cos x$, and $e^{ix}$ are $2\pi$-periodic. Consequently, they are also $2\pi k$-periodic for every integer $k\in\mathbb{Z}$. The function $f(x)=x$ is not periodic. The constant function $f(x)=1$ is $L$-periodic for every $L>0$.
\end{example}

\begin{example}
Let $n\in\mathbb{Z}$. Then the functions
\[
\cos(2\pi n x),\qquad \sin(2\pi n x),\qquad e^{2\pi i n x}
\]
are all $\mathbb{Z}$-periodic (i.e. $1$-periodic).

Another $\mathbb{Z}$-periodic function is the \emph{square wave} $f:\mathbb{R}\to\mathbb{C}$ defined by
\[
 f(x):=\begin{cases}
 1, & x\in\bigl[k, k+\tfrac12\bigr),\\
 0, & x\in\bigl[k+\tfrac12, k+1\bigr),
 \end{cases}
\qquad (k\in\mathbb{Z}),
\]
and extended periodically to all of $\mathbb{R}$.
\end{example}

\begin{lemma}[Basic properties of $C(\mathbb{R}/\mathbb{Z};\mathbb{C})$ (a)]
(Boundedness) If $f\in C(\mathbb{R}/\mathbb{Z};\mathbb{C})$, then $f$ is bounded.
\end{lemma}

\begin{lemma}[Basic properties of $C(\mathbb{R}/\mathbb{Z};\mathbb{C})$ (b)]
(Vector space and algebra properties) If $f,g\in C(\mathbb{R}/\mathbb{Z};\mathbb{C})$, then $f\pm g$ and $fg$ are also in $C(\mathbb{R}/\mathbb{Z};\mathbb{C})$; and if $c\in\mathbb{C}$ then $cf\in C(\mathbb{R}/\mathbb{Z};\mathbb{C})$.
\end{lemma}

\begin{lemma}[Basic properties of $C(\mathbb{R}/\mathbb{Z};\mathbb{C})$ (c)]
(Closure under uniform limits) If $(f_n)$ is a sequence in $C(\mathbb{R}/\mathbb{Z};\mathbb{C})$ converging uniformly to $f$, then $f\in C(\mathbb{R}/\mathbb{Z};\mathbb{C})$.
\end{lemma}

\begin{example}
Let $f(x):=1$ and $g(x):=e^{2\pi i x}$. Then $\langle f,g\rangle=0$.
\end{example}

\begin{lemma}[Properties of the inner product (a)]
(Hermitian) If $f,g\in C(\mathbb{R}/\mathbb{Z};\mathbb{C})$, then $\langle g,f\rangle = \overline{\langle f,g\rangle}$.
\end{lemma}

\begin{lemma}[Properties of the inner product (b)]
(Positivity) If $f\in C(\mathbb{R}/\mathbb{Z};\mathbb{C})$, then $\langle f,f\rangle\ge 0$, and $\langle f,f\rangle=0$ iff $f=0$.
\end{lemma}

\begin{example}
Let $f(x):=e^{2\pi i x}$. Then $\|f\|_2=1$.
\end{example}

\begin{lemma}[Basic properties of $\|\cdot\|_2$ (a)]
(Non-degeneracy) $\|f\|_2=0$ iff $f=0$.
\end{lemma}

proof:
\begin{proof}
Recall $\|f\|_2=\sqrt{\langle f,f\rangle}$. If $f\equiv 0$ then $\|f\|_2=0$.
Conversely, if $\|f\|_2=0$ then $\langle f,f\rangle=0$, hence $f=0$ by Lemma~5.2.5b.
\end{proof}

