\begin{lemma}[Basic properties of $\|\cdot\|_2$ (b)]
(Cauchy--Schwarz) $|\langle f,g\rangle|\le \|f\|_2\,\|g\|_2$.
\end{lemma}

\begin{lemma}[Basic properties of $\|\cdot\|_2$ (c)]
(Triangle inequality) $\|f+g\|_2\le \|f\|_2+\|g\|_2$.
\end{lemma}

\begin{lemma}[Basic properties of $\|\cdot\|_2$ (d)]
(Pythagoras) If $\langle f,g\rangle=0$, then $\|f+g\|_2^2=\|f\|_2^2+\|g\|_2^2$.
\end{lemma}

\begin{lemma}[Basic properties of $\|\cdot\|_2$ (e)]
(Homogeneity) $\|cf\|_2=|c|\,\|f\|_2$.
\end{lemma}

\begin{definition}[Orthogonality and the $L^2$ metric]\label{def:5.2.X}
Let $f,g\in C(\mathbb{R}/\mathbb{Z};\mathbb{C})$.
\begin{enumerate}
  \item We say $f$ and $g$ are \emph{orthogonal} if and only if $\langle f,g\rangle = 0$.
  \item The \emph{$L^2$ metric} on $C(\mathbb{R}/\mathbb{Z};\mathbb{C})$ is defined by
  \[
  d_{L^2}(f,g) := \|f-g\|_2 = \left(\int_{0}^{1} |f(x)-g(x)|^2\,dx\right)^{1/2}.
  \]
\end{enumerate}
\end{definition}

\begin{lemma}[Basic properties of periodic convolution (a)]
(Closure) If $f,g\in C(\mathbb{R}/\mathbb{Z};\mathbb{C})$, then $f*g\in C(\mathbb{R}/\mathbb{Z};\mathbb{C})$.
\end{lemma}

\begin{lemma}[Basic properties of periodic convolution (b)]
(Commutativity) $f*g=g*f$.
\end{lemma}

\begin{lemma}[Basic properties of periodic convolution (c)]
(Bilinearity) $f*(g+h)=f*g+f*h$, $(f+g)*h=f*h+g*h$, and $c(f*g)=(cf)*g=f*(cg)$.
\end{lemma}

\begin{lemma}
For every $\varepsilon>0$ and $0<\delta<1/2$, there exists a trigonometric polynomial $P$ which is a $(\varepsilon,\delta)$ approximation to the identity.
\end{lemma}

