\begin{theorem}
Let $f\in C(\mathbb{R}/\mathbb{Z};\mathbb{C})$. If $\sum_{n=-\infty}^{\infty} |\hat f(n)|$ converges, then $\sum_{n=-\infty}^{\infty} \hat f(n)e_n$ converges uniformly to $f$, i.e.
\[
\lim_{N\to\infty}\left\|f-\sum_{n=-N}^{N}\hat f(n)e_n\right\|_\infty=0.
\]
\end{theorem}
